function updateHUD(){if(!player)return;$('#hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('#hpBar').style.width=`${clamp(player.hp/player.maxHp*100,0,100)}%`;$('#mpText').textContent=`${Math.ceil(player.mana)} / ${player.maxMana}`;$('#mpBar').style.width=`${clamp(player.mana/player.maxMana*100,0,100)}%`;$('#stats').innerHTML=`⚔ ${Math.round(player.atk)} &nbsp; ◆ ${Math.round(player.armor)} &nbsp; ◈ ${Math.round(player.life*100)}%`;$('#gold').textContent=gold;$('#blueScore').textContent=blueScore;$('#redScore').textContent=redScore;$('#clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;updateShop()}
function nearestEnemy(x,y,max=Infinity){let near=null,best=max;for(const e of entities){if(e.dead||e.team==='blue')continue;let d=Math.hypot(e.x-x,e.y-y);if(d<best){best=d;near=e}}return near}
function moveToward(a,b,speed,dt){let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d>1){a.x+=dx/d*speed*dt;a.y+=dy/d*speed*dt}return d}
function damage(target,amount,source){if(!target||target.dead)return;let reduction=target.armor/(100+target.armor);let dmg=Math.max(8,amount*(1-reduction));target.hp-=dmg;fx.push({x:target.x,y:target.y-24,text:`-${Math.round(dmg)}`,life:.7,color:source?.team==='blue'?'#f4d18c':'#f18a7a'});if(particles)for(let i=0;i<5;i++)fx.push({x:target.x,y:target.y,dx:rand(-45,45),dy:rand(-60,10),life:rand(.2,.6),dot:true,color:target.team==='blue'?'#8fe0bc':'#ff7166'});if(target.hp<=0){target.dead=true;if(target.team==='red'){blueScore++;gold+=target.type==='core'?300:target.type==='tower'?110:target.type==='hero'?180:35;if(target.type==='hero'){player.xp+=100;player.hp=Math.min(player.maxHp,player.hp+90);toast('Arauto derrotado! +180 almas');}else if(target.type==='core')endGame(true);else toast(`Inimigo derrotado · +${target.type==='tower'?110:35} almas`)}else if(target.type==='hero'){redScore++;respawn=4;toast('Você caiu em batalha. Retorne em 4 segundos.')}updateHUD();sound(140,.13)}}
function cast(i){if(state!=='playing'||paused||!player||player.dead)return;if(cooldowns[i]>0)return toast('Habilidade recarregando.');let costs=[45,55,50,100],base=[5,9,7,23],cost=costs[i];if(player.mana<cost)return toast('Mana insuficiente.');player.mana-=cost;cooldowns[i]=base[i]*(i===3?1.8:1);let target=nearestEnemy(player.x,player.y,selected.range+200),d=target?dist(player,target):0,dir=pointer.world?Math.atan2(pointer.world.y-player.y,pointer.world.x-player.x):0;
if(i===0){if(target&&d<selected.range+105)damage(target,player.atk*(selected.id==='duelist'||selected.id==='shade'?1.5:1.55),{team:'blue'});else{let tx=player.x+Math.cos(dir)*230,ty=player.y+Math.sin(dir)*230;fx.push({x:player.x,y:player.y,targetX:tx,targetY:ty,life:.45,beam:true,color:selected.color});if(target&&dist(target,{x:tx,y:ty})<90)damage(target,player.atk*1.35,{team:'blue'})}}
if(i===1){if(selected.id==='oracle'||selected.id==='warden'){player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.24);player.shield=2.5;entities.filter(e=>e.team==='blue'&&!e.dead&&dist(e,player)<260).forEach(e=>{e.hp=Math.min(e.maxHp,e.hp+150);fx.push({x:e.x,y:e.y,life:.6,dot:true,color:'#8ce8af'})});toast('Bênção restauradora!')}else{player.marked=5;if(target)target.marked=5;toast('Marca das sombras aplicada!')}}
if(i===2){player.x=clamp(player.x+Math.cos(dir)*150,50,map.w-50);player.y=clamp(player.y+Math.sin(dir)*150,80,map.h-80);player.shield=1.5;fx.push({x:player.x,y:player.y,life:.6,dot:true,color:selected.color});if(selected.id==='duelist'||selected.id==='warden'){if(target&&dist(player,target)<200)damage(target,player.atk*1.5,{team:'blue'})}}
if(i===3){for(const e of entities.filter(e=>e.team==='red'&&!e.dead&&dist(e,player)<330)){damage(e,player.atk*(selected.id==='shade'?2.6:2.1),{team:'blue'});fx.push({x:e.x,y:e.y,life:.65,dot:true,color:'#f3b35b'})}if(selected.id==='oracle'||selected.id==='warden')player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.32);toast(`${selected.skills[i][2]}!`)}sound(280+i*80,.18);updateHUD()}
function autoAttack(dt){if(player.dead)return;player.attackCd-=dt;let target=nearestEnemy(player.x,player.y,player.range+55);if(!target)return;let d=dist(player,target);if(d>player.range){if(keys[' ']||pointer.down)moveToward(player,target,player.speed,dt);return}if(player.attackCd<=0){player.attackCd=selected.id==='ranger'?0.65:.82;damage(target,player.atk*(target.marked>0?1.3:1),{team:'blue'});fx.push({x:player.x,y:player.y,targetX:target.x,targetY:target.y,life:.22,beam:true,color:selected.color});if(player.life)player.hp=Math.min(player.maxHp,player.hp+player.atk*player.life);sound(390,.05)}}
function spawnWave(){for(let i=0;i<3;i++)entities.push(makeEntity('minion','blue',190-i*18,map.h/2+rand(-23,23)));for(let i=0;i<3;i++)entities.push(makeEntity('minion','red',map.w-190+i*18,map.h/2+rand(-23,23)));toast('Uma nova onda de servos entrou na arena.');waveTimer=23}
function update(dt){if(state!=='playing'||paused)return;elapsed+=dt;waveTimer-=dt;enemyTimer-=dt;if(waveTimer<=0)spawnWave();if(enemyTimer<=0){let e=makeEntity('hero','red',map.w-260,map.h/2+rand(-120,120),{hp:(selected.hp*.88)+(elapsed*2),atk:selected.atk*.82+elapsed*.12,icon:'👹',name:'Arauto'});entities.push(e);enemyTimer=Math.max(19,31-elapsed*.06)}
if(player.dead){respawn-=dt;if(respawn<=0){player.dead=false;player.hp=player.maxHp;player.mana=player.maxMana;player.x=270;player.y=map.h/2;toast('Você voltou à batalha!')}return}
let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+moveTouch.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+moveTouch.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}if(dx||dy){player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt}player.x=clamp(player.x,50,map.w-50);player.y=clamp(player.y,90,map.h-90);player.mana=Math.min(player.maxMana,player.mana+8*dt);player.hp=Math.min(player.maxHp,player.hp+1.5*dt);if(player.marked>0)player.marked-=dt;if(player.shield>0)player.shield-=dt;cooldowns=cooldowns.map(x=>Math.max(0,x-dt));
if(pointer.down&&pointer.world){let d=Math.hypot(pointer.world.x-player.x,pointer.world.y-player.y);if(d>player.range*.78){let dx=pointer.world.x-player.x,dy=pointer.world.y-player.y,l=Math.hypot(dx,dy);player.x+=dx/l*player.speed*dt;player.y+=dy/l*player.speed*dt}else{let e=nearestEnemy(pointer.world.x,pointer.world.y,95);if(e)damage(e,0,{team:'blue'});keys[' ']=true}}autoAttack(dt);
for(const e of entities){if(e.dead)continue;e.cool-=dt;if(e.type==='minion'){let enemy=entities.find(o=>!o.dead&&o.team!==e.team&&o.type!=='core'&&dist(o,e)<e.range+o.r);if(enemy){if(e.cool<=0){e.cool=1.3;damage(enemy,e.atk,e)} }else{let dir=e.team==='blue'?1:-1;let goal=e.team==='blue'?entities.find(o=>o.team==='red'&&!o.dead&&o.type==='tower')||entities.find(o=>o.team==='red'&&!o.dead&&o.type==='core'):entities.find(o=>o.team==='blue'&&!o.dead&&o.type==='tower')||entities.find(o=>o.team==='blue'&&!o.dead&&o.type==='core');if(goal){e.x+=dir*e.speed*dt;e.y+=(map.h/2-e.y)*dt*.12}}}
else if(e.type==='hero'&&e.team==='red'){let d=dist(e,player);if(d<e.range){if(e.cool<=0){e.cool=1.15;damage(player,e.atk,{team:'red'})}}else if(d<600)moveToward(e,player,e.speed,dt);else {let tower=entities.find(o=>o.team==='blue'&&!o.dead&&o.type==='tower')||entities.find(o=>o.team==='blue'&&!o.dead&&o.type==='core');if(tower)moveToward(e,tower,e.speed*.7,dt)}}
else if(e.type==='tower'){let target=entities.filter(o=>!o.dead&&o.team!==e.team&&o.type!=='core'&&dist(e,o)<e.range).sort((a,b)=>dist(e,a)-dist(e,b))[0];if(target&&e.cool<=0){e.cool=1.3;damage(target,e.atk,e);fx.push({x:e.x,y:e.y,targetX:target.x,targetY:target.y,life:.3,beam:true,color:e.team==='blue'?'#8fd4da':'#f57967'})}}
else if(e.type==='core'){let near=entities.find(o=>!o.dead&&o.team!==e.team&&o.type!=='core'&&dist(e,o)<180);if(near&&e.cool<=0){e.cool=1.6;damage(near,e.atk,e)}}if(e.marked>0)e.marked-=dt}
fx=fx.filter(f=>{f.life-=dt;if(f.dx){f.x+=f.dx*dt;f.y+=f.dy*dt;f.dy+=40*dt}return f.life>0});entities=entities.filter(e=>!e.dead||e.type==='core');if(Math.floor(elapsed)%2===0&&Math.random()<dt*.55){gold+=1}if(Math.floor(elapsed)%5===0&&Math.random()<dt*.15)updateHUD();camera.x=clamp(player.x-innerWidth*.5,0,map.w-innerWidth);camera.y=clamp(player.y-innerHeight*.53,0,map.h-innerHeight);updateHUD()}
function project(x,y,z=0){return{x:x-camera.x,y:y-camera.y-z}}

