polygon([[e.x-r*.7,e.y],[e.x-r*.8,e.y-r*1.3],[e.x-r*.38,e.y-r*2.15],[e.x+r*.35,e.y-r*2.2],[e.x+r*.8,e.y-r*1.3],[e.x+r*.7,e.y]],isPlayer? '#37333e':'#553b3b',col);polygon([[e.x-r*.48,e.y-r*1.35],[e.x-r*.35,e.y-r*2.1],[e.x+r*.35,e.y-r*2.1],[e.x+r*.5,e.y-r*1.35]],col+'cc','#e8c89a');circle(e.x,e.y-r*2.55,r*.57,isPlayer?'#d8bd9b':'#9e6858','#d6c1a0');polygon([[e.x-r*.61,e.y-r*2.67],[e.x-r*.45,e.y-r*3.1],[e.x-r*.1,e.y-r*2.96],[e.x+r*.2,e.y-r*3.2],[e.x+r*.58,e.y-r*2.65]],'#342b31','#a58b6a');if(isPlayer){circle(e.x-r*.21,e.y-r*2.58,2*s,'#edc77b');circle(e.x+r*.21,e.y-r*2.58,2*s,'#edc77b')}}
