function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
function fillHeroSelect(){let grid=$('#heroGrid');grid.innerHTML='';heroes.forEach(hero=>{let b=document.createElement('button');b.className='hero-pick'+(hero.id===selected.id?' selected':'');b.dataset.hero=hero.id;b.innerHTML=`<div class="hero-art">${hero.icon}</div><div class="pick-name">${hero.name}</div><div class="pick-role">${hero.role}</div><div class="pick-desc">${hero.desc}</div>`;b.onclick=()=>{selected=hero;fillHeroSelect()};grid.append(b)});$('#heroSummary').innerHTML=`<b style="color:#e7c68e">${selected.name} · ${selected.role}</b><br>Vida ${selected.hp} &nbsp;·&nbsp; Dano ${selected.atk} &nbsp;·&nbsp; Alcance ${selected.range}`}
fillHeroSelect();$('#playBtn').onclick=startGame;$('#againBtn').onclick=()=>{$('#result').classList.add('hidden');$('#menu').classList.remove('hidden');$('#hud').style.display='none';state='menu';paused=false};$('#shopBtn').onclick=()=>{if(state==='playing'&&!paused){$('#shop').classList.remove('hidden');updateShop()}};$('#closeShop').onclick=()=>$('#shop').classList.add('hidden');$('#shop').addEventListener('pointerdown',e=>{if(e.target===$('#shop'))$('#shop').classList.add('hidden')});
function openOptions(){if(state==='playing')paused=true;$('#options').classList.remove('hidden')};function closeOptions(){volume=Number($('#volume').value)/100;difficulty=$('#difficulty').value;$('#options').classList.add('hidden');if(state==='playing'){paused=false;toast('Partida retomada.');updateShop()}}$('#menuOptions').onclick=openOptions;$('#closeOptions').onclick=closeOptions;$('#doneOptions').onclick=closeOptions;$('#volume').oninput=e=>volume=Number(e.target.value)/100;$('#particlesToggle').onclick=()=>{particles=!particles;$('#particlesToggle').classList.toggle('on',particles);$('#particlesToggle').textContent=particles?'ATIVAS':'DESATIVADAS'};$('#difficulty').onchange=e=>difficulty=e.target.value;
$('#pauseBtn').onclick=()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶  RETOMAR':'Ⅱ  PAUSAR';if(paused){$('#options').classList.remove('hidden')}else{$('#options').classList.add('hidden');updateShop()}};$('#closeOptions').addEventListener('click',()=>{$('#pauseBtn').textContent='Ⅱ  PAUSAR'});$('#doneOptions').addEventListener('click',()=>{$('#pauseBtn').textContent='Ⅱ  PAUSAR'});
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='b'&&state==='playing'){if($('#shop').classList.contains('hidden'))$('#shop').classList.remove('hidden');else $('#shop').classList.add('hidden');updateShop()}if(k==='escape'){if(!$('#shop').classList.contains('hidden'))$('#shop').classList.add('hidden');else if(state==='playing')$('#pauseBtn').click()}if(k==='q')cast(0);if(k==='w'&&!keys.a&&!keys.s&&!keys.d)cast(1);if(k==='e')cast(2);if(k==='r')cast(3)});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function setPointer(e){let rect=canvas.getBoundingClientRect();pointer.x=e.clientX-rect.left;pointer.y=e.clientY-rect.top;pointer.world={x:camera.x+pointer.x/zoom,y:camera.y+pointer.y/zoom}}
canvas.addEventListener('pointerdown',e=>{if(state!=='playing'||paused)return;setPointer(e);pointer.down=true;canvas.setPointerCapture(e.pointerId);keys[' ']=true});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')setPointer(e);else if(pointer.down)setPointer(e)});canvas.addEventListener('pointerup',e=>{pointer.down=false;keys[' ']=false;setPointer(e)});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const stick=$('#stick');stick.addEventListener('pointerdown',e=>{e.preventDefault();touchId=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===touchId)updateStick(e)});function updateStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),lim=r.width*.35,d=Math.hypot(dx,dy);if(d>lim){dx*=lim/d;dy*=lim/d}moveTouch.x=dx/lim;moveTouch.y=dy/lim;stick.style.setProperty('--sx',`${dx}px`);stick.style.setProperty('--sy',`${dy}px`);stick.style.background=`radial-gradient(circle at calc(50% + ${dx}px) calc(50% + ${dy}px),#d9c39d99 0 15px,#15121a88 16px)`}function endStick(e){if(e.pointerId===touchId){touchId=null;moveTouch={x:0,y:0};stick.style.background='#15121a88'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
// Pause on tab switch to protect a mobile match.
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'){paused=true;$('#pauseBtn').textContent='▶  RETOMAR';$('#options').classList.remove('hidden')}});
})();
</script></body></html>

